// 原Land批次精确source组反例；不模拟战果权限或完整World人物捕获记录。
#include "resident/domains/military/military_actor_condition_write.hpp"
#include <iostream>
using namespace hanmo::resident;
namespace {int checks=0,failures=0;void check(bool x,const char* text){++checks;if(!x){++failures;std::cerr<<text<<'\n';}}}
int main(){MilitaryState s;MilitaryActorChange wound;wound.actor_id="a";wound.status="wounded";wound.army_id="army:1";MilitaryActorChange captured;captured.actor_id="b";captured.status="captured";captured.army_id="army:1";captured.captor_army_id="army:2";MilitaryActorChange dead;dead.actor_id="c";dead.status="dead";dead.army_id="army:3";MilitaryCasualtyFact one;one.id="military:10";one.actor_changes={wound,captured};MilitaryCasualtyFact two;two.id="military:20";two.actor_changes={dead};s.casualty_facts={one,two};std::vector<MilitaryActorChange> changes{wound,captured,dead};check(validate_military_actor_condition_changes(s,changes,{one.id,two.id}).ok,"original two true casualty groups preserve writer order");check(!validate_military_actor_condition_changes(s,changes,{two.id,one.id}).ok,"same actors wrong source group order rejected");check(!validate_military_actor_condition_changes(s,changes,{one.id}).ok,"missing original death source rejected");check(!validate_military_actor_condition_changes(s,changes,{}).ok,"HP write cannot omit all explicit sources");check(!validate_military_actor_condition_changes(s,changes,{one.id,one.id,two.id}).ok,"duplicate receipt cannot pay for repeated writes");check(!validate_military_actor_condition_changes(s,changes,{one.id,"military:404"}).ok,"absent receipt refused");auto modified=changes;modified.back().actor_id="other";check(!validate_military_actor_condition_changes(s,modified,{one.id,two.id}).ok,"same effect on different actor refused");modified=changes;modified.back().army_id="other";check(!validate_military_actor_condition_changes(s,modified,{one.id,two.id}).ok,"real army reference cannot be substituted");modified=changes;modified.front().status="dead";check(!validate_military_actor_condition_changes(s,modified,{one.id,two.id}).ok,"wound does not authorize death");MilitaryCasualtyFact zero;zero.id="military:30";zero.actor_changes={captured};s.casualty_facts.push_back(zero);check(validate_military_actor_condition_changes(s,{captured},{zero.id}).ok,"actual captured-only receipt has no HP or fatigue write");check(validate_military_actor_condition_changes(s,{captured},{}).ok,"existing non-condition return/custody path stays legal");check(validate_military_actor_condition_changes(s,{},{}).ok,"empty group does not invent a source");s.casualty_facts.push_back(one);check(!validate_military_actor_condition_changes(s,changes,{one.id,two.id}).ok,"ambiguous duplicate business receipt refused");std::cout<<"MILITARY_ACTOR_CONDITION_GROUP "<<checks<<"/"<<failures<<" GROUP_ONLY_NOT_WRITER_OR_WORLD\n";return failures?1:0;}
